def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    events: dict[int, int] = {}
    for start, end in meetings:
        if start < end:
            events[start] = events.get(start, 0) + 1
            events[end] = events.get(end, 0) - 1

    active = 0
    total = 0
    prev_time = 0
    for time in sorted(events):
        if active >= k:
            total += time - prev_time
        active += events[time]
        prev_time = time

    return total
